import boto3
import os
from typing import Dict

def get_block_text(block_map: Dict, block_id: str) -> str:
    block = block_map[block_id]
    if 'Text' in block:
        return block['Text']
    text = ''
    if 'Relationships' in block:
        for rel in block['Relationships']:
            if rel['Type'] == 'CHILD':
                for child_id in rel['Ids']:
                    text += get_block_text(block_map, child_id) + ' '
    return text.strip()

def extract_key_value_pairs(document_path: str) -> Dict[str, str]:
    aws_access_key_id = os.getenv('AWS_ACCESS_KEY_ID')
    aws_secret_access_key = os.getenv('AWS_SECRET_ACCESS_KEY')
    region = os.getenv('AWS_DEFAULT_REGION', 'us-east-1')
    if not aws_access_key_id or not aws_secret_access_key:
        raise ValueError("Set AWS_ACCESS_KEY_ID and AWS_SECRET_ACCESS_KEY")
    client = boto3.client(
        'textract',
        aws_access_key_id=aws_access_key_id,
        aws_secret_access_key=aws_secret_access_key,
        region_name=region
    )
    with open(document_path, 'rb') as file:
        document = {'Bytes': file.read()}
    response = client.analyze_document(
        Document=document,
        FeatureTypes=['FORMS']
    )
    blocks = response['Blocks']
    block_map = {block['Id']: block for block in blocks}
    kv_pairs: Dict[str, str] = {}
    for block in blocks:
        if block['BlockType'] == 'KEY_VALUE_SET' and 'ENTITY_TYPES' in block and block['ENTITY_TYPES'][0] == 'KEY':
            key_text = ''
            if 'Relationships' in block:
                for rel in block['Relationships']:
                    if rel['Type'] == 'CHILD':
                        for child_id in rel['Ids']:
                            key_text += get_block_text(block_map, child_id) + ' '
            key_text = key_text.strip()
            value_text = ''
            if 'Relationships' in block:
                for rel in block['Relationships']:
                    if rel['Type'] == 'VALUE':
                        for value_id in rel['Ids']:
                            value_block = block_map[value_id]
                            vtext = ''
                            if 'Relationships' in value_block:
                                for vrel in value_block['Relationships']:
                                    if vrel['Type'] == 'CHILD':
                                        for vchild_id in vrel['Ids']:
                                            vtext += get_block_text(block_map, vchild_id) + ' '
                            value_text = vtext.strip()
                            break
                        break
            if key_text and value_text:
                kv_pairs[key_text] = value_text
    return kv_pairs
